      "Лук нарежьте полукольцами, сладкий перец — полосками, чеснок мелко порубите.",
      "В тяжёлой кастрюле разогрейте масло и обжарьте говядину в 2 захода до корочки, чтобы мясо не тушилось в собственном соку.",
      "Верните всё мясо в кастрюлю, добавьте лук и готовьте 4 минуты, затем вмешайте паприку, томатную пасту и чеснок.",
      "Влейте горячую воду или бульон почти до уровня мяса. Накройте крышкой и тушите 45–55 минут на слабом огне.",
      "Добавьте сладкий перец и готовьте ещё 10 минут; при необходимости подлейте немного воды.",
